import java.util.List;
import java.util.Iterator;

List<String> frutas = List.of("manzana", "banana", "cereza");
Iterator<String> miIterador = frutas.iterator();

System.out.println(miIterador.next()); // manzana
System.out.println(miIterador.next()); // banana
System.out.println(miIterador.next()); // cereza

// En Java los Strings NO son Iterable directamente
String texto = "uva";
java.util.Iterator<Integer> iterador = texto.chars().iterator();

System.out.println((char) iterador.next().intValue()); // u
System.out.println((char) iterador.next().intValue()); // v

import java.util.List;

List<String> tupla = List.of("manzana", "banana", "cereza");

// El for-each de Java hace lo mismo internamente
for (String x : tupla) {
    System.out.println(x);
}
